//! `extensions/index.json`: every extension in the registry with its manifest, README and the
//! SHA-256 of each of its files. Generated by `tomboy ext index` from the `extensions/` folder
//! (CI fails when it is stale); read by the store and the installer.

use std::collections::BTreeMap;
use std::path::Path;

use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

use super::manifest::{
    ALLOWED_EXTENSIONS, API_VERSION, ENTRY, MANIFEST, MAX_ICON_BYTES, MAX_TOTAL_BYTES, Manifest,
};

/// The README shown in the store's detail pane.
pub const README: &str = "README.md";

/// The optional icon file.
pub const ICON: &str = "icon.png";

#[derive(Debug, Clone, Default, Deserialize, Serialize, PartialEq)]
pub struct Index {
    /// The extension API version of the tomboy that generated it.
    pub api: u32,
    /// Sorted by id.
    pub extensions: Vec<Entry>,
}

#[derive(Debug, Clone, Deserialize, Serialize, PartialEq)]
pub struct Entry {
    pub manifest: Manifest,
    /// Path relative to the extension folder (`/`-separated) → SHA-256, lowercase hex.
    pub files: BTreeMap<String, String>,
    /// `README.md`, or "" when there is none.
    #[serde(default)]
    pub readme: String,
}

impl Index {
    pub fn get(&self, id: &str) -> Option<&Entry> {
        self.extensions.iter().find(|e| e.manifest.id == id)
    }
}

/// The index of every extension folder in `dir` (one with a `tomboy.toml`); other entries,
/// like `README.md` or `index.json` itself, are skipped.
pub fn build(dir: &Path) -> Result<Index, String> {
    let entries = std::fs::read_dir(dir).map_err(|e| format!("{}: {e}", dir.display()))?;
    let mut extensions = Vec::new();
    for entry in entries {
        let path = entry.map_err(|e| format!("{}: {e}", dir.display()))?.path();
        if !path.is_dir() || !path.join(MANIFEST).is_file() {
            continue;
        }
        let folder = path.file_name().and_then(|n| n.to_str()).unwrap_or_default().to_string();
        let manifest = Manifest::load(&path).map_err(|e| format!("{folder}: {e}"))?;
        if manifest.id != folder {
            return Err(format!("{folder}: id \"{}\" must match its folder name", manifest.id));
        }
        let files = check_files(&path).map_err(|e| format!("{folder}: {e}"))?;
        let readme = std::fs::read_to_string(path.join(README)).unwrap_or_default();
        extensions.push(Entry { manifest, files, readme });
    }
    extensions.sort_by(|a, b| a.manifest.id.cmp(&b.manifest.id));
    Ok(Index { api: API_VERSION, extensions })
}

/// Pretty JSON with a trailing newline, the same bytes for the same folder.
pub fn render(index: &Index) -> String {
    serde_json::to_string_pretty(index).unwrap_or_default() + "\n"
}

pub fn parse(raw: &str) -> Result<Index, String> {
    serde_json::from_str(raw).map_err(|e| format!("extension index: {e}"))
}

/// Every file of one extension folder → its SHA-256, after checking the folder holds only
/// allowed file types (no symlinks), fits the size limits and has `tomboy.toml` and `init.luau`.
pub fn check_files(dir: &Path) -> Result<BTreeMap<String, String>, String> {
    let mut files = BTreeMap::new();
    let mut total = 0;
    walk(dir, "", &mut files, &mut total)?;
    for required in [MANIFEST, ENTRY] {
        if !files.contains_key(required) {
            return Err(format!("{required} is missing"));
        }
    }
    Ok(files)
}

fn walk(dir: &Path, prefix: &str, files: &mut BTreeMap<String, String>, total: &mut u64) -> Result<(), String> {
    let entries = std::fs::read_dir(dir).map_err(|e| format!("{}: {e}", dir.display()))?;
    for entry in entries {
        let entry = entry.map_err(|e| format!("{}: {e}", dir.display()))?;
        let name = entry.file_name().into_string().map_err(|n| format!("{n:?}: file names must be UTF-8"))?;
        let rel = format!("{prefix}{name}");
        let meta = entry.path().symlink_metadata().map_err(|e| format!("{rel}: {e}"))?;
        if meta.is_dir() {
            walk(&entry.path(), &format!("{rel}/"), files, total)?;
            continue;
        }
        if !meta.is_file() {
            return Err(format!("{rel}: only plain files are allowed (no symlinks)"));
        }
        check_path(&rel)?;
        check_size(&rel, meta.len(), total)?;
        let bytes = std::fs::read(entry.path()).map_err(|e| format!("{rel}: {e}"))?;
        files.insert(rel, sha256_hex(&bytes));
    }
    Ok(())
}

/// Refuses a file path that could escape the extension folder or has a type not allowed.
pub fn check_path(rel: &str) -> Result<(), String> {
    let safe = !rel.is_empty()
        && !rel.starts_with('/')
        && !rel.contains('\\')
        && rel.split('/').all(|c| !c.is_empty() && c != "." && c != ".." && !c.contains(':'));
    if !safe {
        return Err(format!("{rel}: not a plain relative path"));
    }
    let ext = rel.rsplit_once('.').map(|(_, e)| e).unwrap_or_default();
    if !ALLOWED_EXTENSIONS.contains(&ext) {
        return Err(format!("{rel}: file type not allowed (only .{})", ALLOWED_EXTENSIONS.join(" .")));
    }
    Ok(())
}

/// Adds `len` to `total`, refusing an icon or an extension that gets too big.
pub fn check_size(rel: &str, len: u64, total: &mut u64) -> Result<(), String> {
    if rel == ICON && len > MAX_ICON_BYTES {
        return Err(format!("{ICON} is over {} KB", MAX_ICON_BYTES / 1024));
    }
    *total += len;
    if *total > MAX_TOTAL_BYTES {
        return Err(format!("files are over {} KB together", MAX_TOTAL_BYTES / 1024));
    }
    Ok(())
}

pub fn sha256_hex(bytes: &[u8]) -> String {
    Sha256::digest(bytes).iter().map(|b| format!("{b:02x}")).collect()
}

#[cfg(test)]
pub(crate) mod tests {
    use super::*;
    use std::path::PathBuf;

    pub const TOML: &str = r#"
id = "demo"
name = "Demo"
version = "1.0.0"
api = 1
description = "A demo"
author = "someone"
license = "MIT"

[[commands]]
id = "show"
title = "Show"

[permissions]
net = ["example.com"]
"#;

    /// A fresh empty directory under the system temp dir.
    pub fn temp(name: &str) -> PathBuf {
        use std::sync::atomic::{AtomicU32, Ordering};
        static N: AtomicU32 = AtomicU32::new(0);
        let n = N.fetch_add(1, Ordering::Relaxed);
        let dir = std::env::temp_dir().join(format!("tomboy-test-{name}-{}-{n}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    /// `dir/<id>/` with a manifest (from `TOML`), `init.luau` and a README.
    pub fn write_ext(dir: &Path, id: &str, version: &str) -> PathBuf {
        let ext = dir.join(id);
        std::fs::create_dir_all(&ext).unwrap();
        let toml = TOML.replace("id = \"demo\"", &format!("id = \"{id}\"")).replace("1.0.0", version);
        std::fs::write(ext.join(MANIFEST), toml).unwrap();
        std::fs::write(ext.join(ENTRY), "return { show = function(ctx) return nil end }\n").unwrap();
        std::fs::write(ext.join(README), "# Demo\n").unwrap();
        ext
    }

    #[test]
    fn builds_sorted_and_round_trips() {
        let dir = temp("index-build");
        write_ext(&dir, "zeta", "1.0.0");
        write_ext(&dir, "alpha", "2.0.0");
        std::fs::create_dir_all(dir.join("alpha/lib")).unwrap();
        std::fs::write(dir.join("alpha/lib/util.luau"), "return {}\n").unwrap();
        std::fs::write(dir.join("README.md"), "registry readme").unwrap();
        std::fs::write(dir.join("index.json"), "{}").unwrap();
        let index = build(&dir).unwrap();
        let ids: Vec<_> = index.extensions.iter().map(|e| e.manifest.id.as_str()).collect();
        assert_eq!(ids, ["alpha", "zeta"]);
        let alpha = index.get("alpha").unwrap();
        assert_eq!(alpha.readme, "# Demo\n");
        assert!(alpha.files.contains_key("lib/util.luau"));
        assert_eq!(alpha.files["lib/util.luau"], sha256_hex(b"return {}\n"));
        let raw = render(&index);
        assert!(raw.ends_with("}\n"));
        assert_eq!(parse(&raw).unwrap(), index);
        assert_eq!(render(&build(&dir).unwrap()), raw);
        std::fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn id_must_match_folder() {
        let dir = temp("index-folder");
        let ext = write_ext(&dir, "demo", "1.0.0");
        std::fs::rename(ext, dir.join("other")).unwrap();
        assert!(build(&dir).unwrap_err().contains("folder name"));
        std::fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn refuses_bad_files() {
        let dir = temp("index-files");
        let ext = write_ext(&dir, "demo", "1.0.0");
        assert!(check_files(&ext).is_ok());
        std::fs::write(ext.join("run.sh"), "rm -rf /").unwrap();
        assert!(check_files(&ext).unwrap_err().contains("not allowed"));
        std::fs::remove_file(ext.join("run.sh")).unwrap();
        std::fs::write(ext.join(ICON), vec![0u8; MAX_ICON_BYTES as usize + 1]).unwrap();
        assert!(check_files(&ext).unwrap_err().contains("icon.png"));
        std::fs::write(ext.join(ICON), vec![0u8; 10]).unwrap();
        std::fs::write(ext.join("big.json"), vec![b' '; MAX_TOTAL_BYTES as usize]).unwrap();
        assert!(check_files(&ext).unwrap_err().contains("together"));
        std::fs::remove_file(ext.join("big.json")).unwrap();
        std::fs::remove_file(ext.join(ENTRY)).unwrap();
        assert!(check_files(&ext).unwrap_err().contains("init.luau"));
        std::fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn paths() {
        assert!(check_path("init.luau").is_ok());
        assert!(check_path("lib/a.luau").is_ok());
        for bad in ["../x.luau", "/etc/x.toml", "a//b.luau", "./a.luau", "a\\b.luau", "C:x.luau", "x.sh", "noext"] {
            assert!(check_path(bad).is_err(), "{bad}");
        }
    }
}
